begin; create extension if not exists pgtap with schema extensions; set search_path=public,extensions; select plan(28);
select has_table('public','contract_identification_audit_events','audit exists');
select has_function('public','complete_materialized_contract_identification_transaction',array['uuid','boolean','text','boolean','text','text'],'RPC exists');
select ok(not has_function_privilege('anon','public.complete_materialized_contract_identification_transaction(uuid,boolean,text,boolean,text,text)','EXECUTE'),'anon denied');
select ok(has_function_privilege('authenticated','public.complete_materialized_contract_identification_transaction(uuid,boolean,text,boolean,text,text)','EXECUTE'),'authenticated granted');
insert into organizations(id,name,slug) values('e6100000-0000-4000-8000-000000000001','C6','c6'),('e6100000-0000-4000-8000-000000000002','C6B','c6b');
insert into auth.users(id) values('e6200000-0000-4000-8000-000000000001'),('e6200000-0000-4000-8000-000000000002');
insert into profiles(id,organization_id,name,email,role) values('e6200000-0000-4000-8000-000000000001','e6100000-0000-4000-8000-000000000001','M','m@c6.test','master'),('e6200000-0000-4000-8000-000000000002','e6100000-0000-4000-8000-000000000002','S','s@c6.test','sdr');
insert into crm_leads(id,organization_id,nome) values('e6300000-0000-4000-8000-000000000001','e6100000-0000-4000-8000-000000000001','Lead');
insert into clients(id,organization_id,name) values('e6400000-0000-4000-8000-000000000001','e6100000-0000-4000-8000-000000000001','Client');
insert into administrators(id,organization_id,name,slug) values('e6500000-0000-4000-8000-000000000001','e6100000-0000-4000-8000-000000000001','Rodobens','rodobens');
create function pg_temp.snap(p_sim text,p_key text) returns jsonb language sql as $$select jsonb_build_object('schemaVersion','commercial-proposal/v1','proposalKind','patrimonial_strategy','provenance',jsonb_build_object('authority','server_derived','simulationId',p_sim,'calculationEngineKey','e','calculationEngineVersion','1','financialProductKey','p','financialProductVersion','1'),'product',jsonb_build_object('productKey','p','productVersion','1','displayName','P','administratorTechnicalId','e6500000-0000-4000-8000-000000000001','administratorReferenceKey','rodobens','administratorDisplayName','Rodobens','groupCode','2227','termMonths',10),'strategy',jsonb_build_object('quotaCount',1,'totalCredit',jsonb_build_object('amountCents',1000000,'currency','BRL')),'composition',jsonb_build_array(jsonb_build_object('itemKey',p_key,'position',1,'commercialCatalogCode','CAT','credit',jsonb_build_object('amountCents',1000000,'currency','BRL'),'termMonths',10,'installmentPhases',jsonb_build_array(jsonb_build_object('phaseKey','p','startInstallment',1,'endInstallment',10,'installmentAmount',jsonb_build_object('amountCents',100000,'currency','BRL'))))),'commercialTerms','{}'::jsonb,'disclosures','[]'::jsonb)$$;
create function pg_temp.make(p_prop uuid,p_sim uuid,p_key text,p_idem text) returns uuid language plpgsql as $$declare s jsonb:=pg_temp.snap(p_sim::text,p_key); cid uuid; begin perform set_config('request.jwt.claim.role','service_role',true); perform create_server_derived_patrimonial_proposal_transaction('e6100000-0000-4000-8000-000000000001','e6200000-0000-4000-8000-000000000001','e6300000-0000-4000-8000-000000000001',p_sim,p_prop,p_idem,repeat('a',64),'{"i":true}','{"r":true}',s,commercial_proposal_terms_hash(s)); perform set_config('request.jwt.claim.sub','e6200000-0000-4000-8000-000000000001',true); perform approve_commercial_proposal_transaction(p_prop); perform materialize_approved_commercial_proposal_transaction(p_prop,'e6400000-0000-4000-8000-000000000001',p_idem||'-mat'); select c.id into cid from contracts c join contract_materializations m on m.id=c.contract_materialization_id where m.source_proposal_version_id=p_prop; return cid; end$$;
create temp table ids(n int,id uuid); insert into ids values(1,pg_temp.make('e6600000-0000-4000-8000-000000000001','e6700000-0000-4000-8000-000000000001','a','c6-create-1')),(2,pg_temp.make('e6610000-0000-4000-8000-000000000002','e6710000-0000-4000-8000-000000000002','b','c6-create-2'));
grant select on ids to authenticated;
select set_config('request.jwt.claim.role','authenticated',true); select set_config('request.jwt.claim.sub','e6200000-0000-4000-8000-000000000001',true); set local role authenticated;
select is((complete_materialized_contract_identification_transaction((select id from ids where n=1),true,' 001-A/2 ',false,null,null)->>'outcome'),'completed','number completed');
select is((select contract_number from contracts where id=(select id from ids where n=1)),'001-A/2','number format preserved');
select is((complete_materialized_contract_identification_transaction((select id from ids where n=1),false,null,true,' 0007 ',null)->>'outcome'),'completed','quota completed progressively');
select is((select contract_quota from contracts where id=(select id from ids where n=1)),'0007','quota zeros preserved');
select is((complete_materialized_contract_identification_transaction((select id from ids where n=1),true,'001-A/2',true,'0007',null)->>'outcome'),'unchanged','retry unchanged');
select is((select count(*)::integer from contract_identification_audit_events where contract_id=(select id from ids where n=1)),2,'unchanged has no audit');
select throws_ok(format('select complete_materialized_contract_identification_transaction(%L,true,%L,false,null,null)',(select id from ids where n=1),'002'),'P0001','CID_REASON_REQUIRED','correction needs reason');
select is((complete_materialized_contract_identification_transaction((select id from ids where n=1),true,'002',false,null,'Administradora corrigiu')->>'outcome'),'corrected','correction succeeds');
select ok((select before_values->>'contractNumber'='001-A/2' and after_values->>'contractNumber'='002' and origin='manual' from contract_identification_audit_events where event_type='contract_identification_corrected'),'before after and manual origin');
select is((complete_materialized_contract_identification_transaction((select id from ids where n=2),true,'003',false,null,null)->>'outcome'),'completed','second contract initial number set');
select throws_ok(format('select complete_materialized_contract_identification_transaction(%L,false,null,true,%L,null)',(select id from ids where n=2),'0007'),'P0001','CID_QUOTA_CONFLICT','group quota duplicate blocked');
select throws_ok(format('select complete_materialized_contract_identification_transaction(%L,true,%L,false,null,%L)',(select id from ids where n=2),'002','reason'),'P0001','CID_NUMBER_CONFLICT','number duplicate blocked');
select throws_ok(format('select complete_materialized_contract_identification_transaction(%L,false,null,false,null,null)',(select id from ids where n=1)),'P0001','CID_NO_FIELDS','no fields blocked');
select throws_ok(format('select complete_materialized_contract_identification_transaction(%L,true,%L,false,null,null)',(select id from ids where n=1),''),'P0001','CID_NUMBER_INVALID','empty blocked');
select throws_ok(format('update contracts set contract_number=%L where id=%L','bypass',(select id from ids where n=1)),'42501',null,'authenticated direct generic update blocked');
reset role;
select set_config('app.contract_identification_origin','',true);
select throws_ok(format('update contracts set contract_number=%L where id=%L','bypass',(select id from ids where n=1)),'P0001','CID_IDENTIFICATION_COMMAND_REQUIRED','database guard blocks privileged generic update');
select lives_ok(format('update contracts set status=%L where id=%L','active',(select id from ids where n=1)),'identified materialized contract can pass activation gate');
select throws_ok(format('update contracts set status=%L where id=%L','active',(select id from ids where n=2)),'P0001','CID_IDENTIFICATION_REQUIRED_FOR_ACTIVATION','incomplete materialized contract cannot activate');
insert into contracts(id,organization_id,status,credit_amount) values('e6800000-0000-4000-8000-000000000001','e6100000-0000-4000-8000-000000000001','draft',0);
select lives_ok($$update contracts set contract_number='LEG-1',contract_quota='L-1',status='active' where id='e6800000-0000-4000-8000-000000000001'$$,'legacy remains compatible');
select throws_ok($$update contract_identification_audit_events set reason='x' where true$$,'P0001','CONTRACT_IDENTIFICATION_AUDIT_IMMUTABLE','audit update blocked');
select throws_ok($$delete from contract_identification_audit_events where true$$,'P0001','CONTRACT_IDENTIFICATION_AUDIT_IMMUTABLE','audit delete blocked');
select is((select count(*)::integer from contract_commission_snapshots),0,'no commission effect');
select is((select count(*)::integer from expected_revenue_entries),0,'no revenue effect');
select set_config('request.jwt.claim.sub','e6200000-0000-4000-8000-000000000002',true); set local role authenticated;
select throws_ok(format('select complete_materialized_contract_identification_transaction(%L,true,%L,false,null,null)',(select id from ids where n=1),'X'),'P0001','CID_ACTOR_FORBIDDEN','sdr denied');
select * from finish(); rollback;
